def send_events_concurrently(n: int, llm_session: LLMUsageSession) -> None:
    success_count = 0
    failure_count = 0

    with ThreadPoolExecutor(max_workers=10) as executor:
        futures = [executor.submit(send_event, llm_session) for _ in range(n)]

        for future in as_completed(futures):
            try:
                future.result()
                success_count += 1
            except Exception:
                failure_count += 1

            # Print the current status on the same line
            print(
                f"\rSuccessfully sent: {success_count} | Failed: {failure_count} | {llm_session.events_sent}",
                end="",
            )

    # Final summary
    print(
        f"\nFinal count - Successfully sent: {success_count} | Failed: {failure_count}"
    )


def send_events(n: int, llm_session: LLMUsageSession) -> None:
    success_count = 0
    failure_count = 0

    system_prompt = "You are a software engineering expert that writes a detailed description of a software codebase."
    user_prompt = "explain pythonic code in one sentence."
    temp = 0.0
    for i in range(n):
        response = llm_session.generate_response(
            system_prompt=system_prompt,
            user_prompt=user_prompt,
            output_cfg=OutputConfig.default(),
            model="gpt-4o-2024-08-06",
            temperature=round(temp, 1),
            request_timeout=300,
        )
        print(f"i: {i}: temp:{round(temp, 1)}")
        print(response)
        temp += 0.2

    print(
        f"\nFinal count - Successfully sent: {success_count} | Failed: {failure_count}"
    )


def main(n: int) -> None:
    meta = UsageSessionMetadata(content_type="codebase", content_id="some codebase id")
    with LLMUsageSession("org_s76pU1v8LAYhTOWB", "eric", meta) as llm_session:
        send_events_concurrently(n, llm_session)
